// Directional intra prediction with runtime angle_delta (no edge filter, no
// upsample), vs the SW reference over the 8 directional modes x angle_delta
// -3..3, fully-available references.
void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  for (final bs in [4, 8]) {
    test(
      'HarborIntraDirAngle bs=$bs matches predictIntraRaw (angle_delta)',
      () async {
        final t = HarborIntraDirAngle(bs: bs);
        final clk = SimpleClockGenerator(10).clk;
        final mode = Logic(name: 'mode', width: 4);
        final ad = Logic(name: 'angle_delta', width: 4);
        final above = Logic(name: 'above', width: 2 * bs * 8);
        final left = Logic(name: 'left', width: 2 * bs * 8);
        final corner = Logic(name: 'corner', width: 8);
        t.input('mode').srcConnection! <= mode;
        t.input('angle_delta').srcConnection! <= ad;
        t.input('above').srcConnection! <= above;
        t.input('left').srcConnection! <= left;
        t.input('corner').srcConnection! <= corner;
        await t.build();
        Simulator.setMaxSimTime(30000000);
        unawaited(Simulator.run());

        BigInt packB(List<int> b) {
          var v = BigInt.zero;
          for (var i = 0; i < b.length; i++) {
            v |= BigInt.from(b[i] & 0xff) << (i * 8);
          }
          return v;
        }

        final rng = Random(0xD17 + bs);
        var gi = 0;
        for (var iter = 0; iter < 30; iter++) {
          final aSrc = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
          final lSrc = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
          final cr = rng.nextInt(256);
          // constructed references (fully available, nTopRight=nBottomLeft=0).
          final a2 = [
            for (var i = 0; i < 2 * bs; i++) i < bs ? aSrc[i] : aSrc[bs - 1],
          ];
          final l2 = [
            for (var i = 0; i < 2 * bs; i++) i < bs ? lSrc[i] : lSrc[bs - 1],
          ];

          for (var m = 1; m <= 8; m++) {
            for (var d = -3; d <= 3; d++) {
              mode.put(m);
              ad.put(d & 0xF);
              above.put(packB(a2));
              left.put(packB(l2));
              corner.put(cr);
              await clk.nextPosedge;

              final want = _gold[bs]![gi++];
              final pv = t.output('pred').value.toBigInt();
              final got = [
                for (var p = 0; p < bs * bs; p++)
                  ((pv >> (p * 8)) & BigInt.from(0xff)).toInt(),
              ];
              expect(
                got,
                equals(want),
                reason: 'bs=$bs mode=$m delta=$d iter=$iter',
              );
            }
          }
        }
        await Simulator.endSimulation();
      },
    );
  }
}
